SELECT BOK_SCENECONFIG.NODE_ID AS id,
BTD1.DICT_NAME AS text,
BTD1.DICT_SOURCE AS col
FROM 
BOK_SCENECONFIG LEFT JOIN BOK_TABLEDICT BTD1 ON BOK_SCENECONFIG.NODE_ID = BTD1.DICT_ID AND BTD1.DICT_TYPE = #{DATA_TYPEP}
WHERE BOK_SCENECONFIG.FSCENE_NODEID = #{sceneNodeId}

SELECT DICT_ID as id,
DICT_NAME as text
FROM BOK_TABLEDICT
WHERE TABLE_ID = #{tableId}
AND DICT_TYPE = #{DICT_TYPEN}

SELECT COUNT(1) FROM BOK_SCENECONFIG
WHERE BOOKSET_ID = #{booksetId}
    AND FSCENE_NODEID = #{fsceneNodeid}
    AND NODE_ID = #{nodeId}
    AND NODE_VALUE = #{nodeValue}

     AND SCENE_NODE_ID <> #{sceneNodeId}

SELECT DICT_ID AS id,
    DICT_NAME AS text,
    DICT_SOURCE AS col
FROM BOK_TABLEDICT
WHERE TABLE_ID = #{nodeId}
AND DICT_TYPE = #{DATA_TYPEP}

    AND DICT_ID NOT IN (
        SELECT NODE_ID FROM BOK_SCENECONFIG WHERE  INSTR(#{sceneNodeId}, SCENE_NODE_ID) = 1
    )

SELECT COUNT(1) FROM BOK_SCENECONFIG WHERE 

    FSCENE_NODEID = #{fsceneNodeid}


    FSCENE_NODEID is null

AND BOOKSET_ID = #{booksetId}
AND NODE_ID = #{nodeId}
AND NODE_VALUE = #{nodeValue}
